def find_cg_source() -> Path:
    env = os.environ.get('PTCG_CG_DIR')
    if env:
        candidate = Path(env)
        if (candidate / 'api.py').is_file() and (candidate / 'libcg.so').is_file():
            return candidate
    direct = [
        '/kaggle/input/competitions/pokemon-tcg-ai-battle/sample_submission/cg',
        '/kaggle/input/competitions/pokemon-tcg-ai-battle/sample_submission/sample_submission/cg',
        '/kaggle/input/pokemon-tcg-ai-battle/sample_submission/cg',
        '/kaggle/input/pokemon-tcg-ai-battle/sample_submission/sample_submission/cg',
    ]
    for raw in direct:
        candidate = Path(raw)
        if (candidate / 'api.py').is_file() and (candidate / 'libcg.so').is_file():
            return candidate
    raise FileNotFoundError('Official cg SDK not found')

build = WORK / 'v12_identity_safe_submission'
if build.exists():
    shutil.rmtree(build)
build.mkdir(parents=True)
for name in ('main.py', 'deck.csv'):
    shutil.copy2(WORK / name, build / name)
shutil.copytree(find_cg_source(), build / 'cg')
for cache in build.rglob('__pycache__'):
    shutil.rmtree(cache)
for bytecode in list(build.rglob('*.pyc')) + list(build.rglob('*.pyo')):
    bytecode.unlink()

archive = WORK / 'submission.tar.gz'
if archive.exists():
    archive.unlink()
with tarfile.open(archive, 'w:gz') as tar:
    tar.add(build / 'main.py', arcname='main.py')
    tar.add(build / 'deck.csv', arcname='deck.csv')
    tar.add(build / 'cg', arcname='cg')

with tarfile.open(archive, 'r:gz') as tar:
    names = tar.getnames()
required = {'main.py', 'deck.csv', 'cg/api.py', 'cg/game.py', 'cg/sim.py', 'cg/libcg.so'}
assert required <= set(names)
assert len(names) == 12
assert not any('__pycache__' in name or name.endswith(('.pyc', '.pyo')) for name in names)
print('archive:', archive, 'bytes:', archive.stat().st_size)


#%%CELL%%

old_cwd = Path.cwd()
sys.path.insert(0, str(build))
os.chdir(build)
try:
    env = {'__name__': '__main__'}
    source = (build / 'main.py').read_text(encoding='utf-8')
    exec(compile(source, 'main.py', 'exec'), env)
    callables = [(name, value) for name, value in env.items() if callable(value)]
    selected_name, selected = callables[-1]
    probes = {
        'empty': {},
        'null-select': {'current': None, 'select': None},
        'partial-current': {'current': {'players': []}, 'select': None},
    }
    probe_rows = []
    for label, payload in probes.items():
        result = selected(payload)
        probe_rows.append({'label': label, 'length': len(result), 'equals_deck_csv': result == deck_ids})
        assert isinstance(result, list) and result == deck_ids
    loader_receipt = {
        'receipt_type': 'ptcg_v12_identity_safe_loader_gate',
        'selected_last_callable': selected_name,
        'signature': str(inspect.signature(selected)),
        'callable_tail': [name for name, _ in callables[-10:]],
        'startup_lengths': [row['length'] for row in probe_rows],
        'probes': probe_rows,
        'gate': 'PASS' if selected_name == 'competition_entrypoint' else 'FAIL',
    }
    assert loader_receipt['gate'] == 'PASS'
    (WORK / 'v12_loader_receipt.json').write_text(json.dumps(loader_receipt, indent=2)+'\n', encoding='utf-8')
    print(json.dumps(loader_receipt, indent=2))

    env['SEARCH_TIME_BUDGET'] = 0.05
    from cg.api import to_observation_class
    from cg.game import battle_finish, battle_select, battle_start
    observation, started = battle_start(deck_ids, deck_ids)
    if observation is None:
        raise RuntimeError(f'battle_start failed: {started}')
    steps = 0
    try:
        while steps < 260:
            state = to_observation_class(observation).current
            if state.result >= 0:
                break
            choices = selected(observation)
            legal = observation['select']
            assert isinstance(choices, list) and all(isinstance(index, int) for index in choices)
            assert int(legal['minCount']) <= len(choices) <= int(legal['maxCount'])
            assert all(0 <= index < len(legal['option']) for index in choices)
            observation = battle_select(choices)
            steps += 1
        else:
            raise TimeoutError('self-game exceeded 260 legal selections')
    finally:
        battle_finish()
    print('budget-clamped official-engine self-game completed in', steps, 'selections')
finally:
    os.chdir(old_cwd)
    if str(build) in sys.path:
        sys.path.remove(str(build))


